/* ===== BIOLOGIA unità 1–4: domande in più, test d'ingresso, spiegazioni (b1a–b4d) ===== */
BIO_QB.push(
{t:"b1a",k:"m",q:"Quale di queste NON è una proprietà fondamentale della materia vivente?",o:["crescita per semplice deposito di materia sulla superficie, come un cristallo", "metabolismo", "omeostasi", "capacità di evolvere", "risposta agli stimoli"],a:0,s:"Un cristallo cresce per accrescimento, ma non ha metabolismo né omeostasi: non è vivo."},
{t:"b1a",k:"m",q:"Secondo l'albero della vita basato sull'rRNA (Woese), gli Archei sono evolutivamente più vicini a:",o:["i Batteri Gram-positivi", "gli Eucarioti", "i virus", "i Batteri Gram-negativi", "nessun dominio: sono la radice di tutti"],a:1,s:"Per le macchine di trascrizione e traduzione gli Archei assomigliano agli Eucarioti."},
{t:"b1a",k:"m",q:"Il virus dell'influenza ha un genoma a RNA a singolo filamento di polarità negativa. Quale enzima deve portare già pronto nel virione?",o:["una trascrittasi inversa", "una DNA polimerasi", "una RNA polimerasi RNA-dipendente", "una telomerasi", "una DNA ligasi"],a:2,s:"L'RNA negativo non può essere tradotto: va prima copiato in mRNA (positivo), e la cellula non ha enzimi per farlo."},
{t:"b1a",k:"m",q:"Qual è l'ordine corretto delle tappe nel ciclo di un retrovirus?",o:["ingresso → integrazione dell'RNA → replicazione dell'RNA → lisi", "integrazione → trascrizione inversa → traduzione → gemmazione", "ingresso → trascrizione inversa → integrazione → trascrizione e traduzione → assemblaggio e gemmazione", "ingresso → trascrizione → trascrizione inversa → integrazione → gemmazione", "traduzione dell'RNA genomico → trascrizione inversa → lisi"],a:2,s:"Prima si fa il DNA (trascrittasi inversa), poi l'integrasi lo inserisce (provirus), da cui la cellula trascrive i nuovi RNA virali."},
{t:"b1a",k:"m",q:"Quale modalità di ingresso in una cellula animale è possibile SOLO per un virus dotato di involucro (envelope)?",o:["endocitosi mediata da recettori", "legame a un recettore specifico", "macropinocitosi", "fusione dell'involucro con la membrana plasmatica", "fagocitosi da parte di un macrofago"],a:3,s:"Solo un involucro lipidico può fondersi con una membrana; i virus nudi entrano per endocitosi."},
{t:"b1a",k:"m",q:"Un profago lambda passa dal ciclo lisogenico a quello litico tipicamente quando:",o:["il terreno contiene lattosio", "il batterio coniuga", "il batterio viene colorato con il metodo di Gram", "il batterio forma la capsula", "il DNA del batterio viene danneggiato (per esempio dai raggi UV)"],a:4,s:"Il danno al DNA attiva la risposta SOS che inattiva il repressore del fago: il profago si stacca ed entra in ciclo litico."},
{t:"b1a",k:"m",q:"Quale di questi NON può costituire il genoma di un virus?",o:["DNA e RNA insieme come due genomi nello stesso virione", "DNA a doppio filamento", "RNA a singolo filamento", "RNA a doppio filamento", "DNA a singolo filamento"],a:0,s:"Ogni virus ha un solo tipo di acido nucleico come genoma: DNA oppure RNA."},
{t:"b1a",k:"m",q:"Un virus nudo (senza involucro) di solito esce dalla cellula animale:",o:["per gemmazione dalla membrana", "per lisi della cellula", "per coniugazione", "per esocitosi di ribosomi", "per trasduzione"],a:1,s:"Senza envelope non può prendere membrana con la gemmazione: viene liberato quando la cellula si rompe."},
{t:"b1a",k:"c",q:"La parte proteica che racchiude e protegge l'acido nucleico di un virus si chiama ____.",a:["CAPSIDE"],s:"Fatto di subunità chiamate capsomeri."},
{t:"b1a",k:"c",q:"HIV infetta i linfociti T helper perché la sua glicoproteina gp120 si lega al recettore ____ (sigla).",a:["CD4"],s:"Con il corecettore CCR5 o CXCR4: il recettore decide quali cellule il virus può infettare."},
{t:"b1a",k:"c",q:"La frase «omnis cellula e cellula», cardine della teoria cellulare, è attribuita a Rudolf ____.",a:["VIRCHOW"],s:"Ogni cellula deriva da una cellula preesistente."},
{t:"b1b",k:"m",q:"Nella colorazione di Gram, quale passaggio distingue i due gruppi perché decolora solo i Gram-negativi?",o:["il cristalvioletto", "la soluzione di Lugol (iodio)", "il lavaggio con alcol o acetone", "la safranina", "il fissaggio alla fiamma"],a:2,s:"L'alcol scioglie la membrana esterna e il peptidoglicano sottile non trattiene il colorante; la safranina poi li colora di rosa."},
{t:"b1b",k:"m",q:"Il lipopolisaccaride (LPS, endotossina) si trova:",o:["nella parete spessa dei Gram-positivi", "nella membrana degli Archei", "nel foglietto esterno della membrana esterna dei Gram-negativi", "nel citoplasma di tutti i batteri", "nei ribosomi 70S"],a:2,s:"È tipico dei Gram-negativi e scatena febbre e shock settico."},
{t:"b1b",k:"m",q:"Quale struttura batterica protegge soprattutto dalla fagocitosi da parte dei globuli bianchi?",o:["il flagello", "le fimbrie", "il nucleoide", "la capsula", "il plasmide"],a:3,s:"La capsula polisaccaridica rende difficile ai fagociti afferrare il batterio."},
{t:"b1b",k:"m",q:"Quale caratteristica distingue gli Archei dai Batteri?",o:["l'assenza di nucleo", "la presenza di mitocondri", "ribosomi 80S", "cromosomi lineari multipli", "lipidi di membrana con legami etere e assenza di peptidoglicano"],a:4,s:"Entrambi sono procarioti, ma la chimica di membrana e parete è diversa."},
{t:"b1b",k:"m",q:"Nella trasformazione batterica il batterio ricevente:",o:["assorbe DNA libero presente nell'ambiente", "riceve DNA portato da un batteriofago", "riceve un plasmide attraverso un pilo", "si fonde con un altro batterio", "scambia ribosomi con il donatore"],a:0,s:"Esperimento di Griffith: i pneumococchi innocui diventano virulenti prendendo DNA dai batteri uccisi."},
{t:"b1b",k:"m",q:"Un batterio F⁺ coniuga con un batterio F⁻. Al termine, di solito:",o:["il donatore diventa F⁻", "entrambi sono F⁺", "entrambi sono F⁻", "il ricevente viene lisato", "il donatore perde il cromosoma"],a:1,s:"Il plasmide F viene copiato mentre passa: il donatore ne conserva una copia e il ricevente ne riceve un'altra."},
{t:"b1b",k:"m",q:"Il flagello batterico differisce da quello eucariotico perché:",o:["è fatto di microtubuli disposti 9+2", "si muove grazie alla dineina", "è un filamento di flagellina fatto ruotare da un motore alla base", "è rivestito da membrana plasmatica", "serve per la coniugazione"],a:2,s:"Il motore batterico è alimentato dal flusso di protoni; il flagello eucariotico invece ondeggia grazie alla dineina."},
{t:"b1b",k:"m",q:"Le penicilline non danneggiano le nostre cellule perché bloccano la sintesi di:",o:["colesterolo", "ribosomi 80S", "DNA mitocondriale", "peptidoglicano", "cheratina"],a:3,s:"Il peptidoglicano esiste solo nella parete batterica."},
{t:"b1b",k:"m",q:"Le fimbrie (pili comuni) servono soprattutto a:",o:["muovere il batterio", "trasferire plasmidi", "produrre ATP", "proteggere dalla disidratazione", "far aderire il batterio ai tessuti dell'ospite"],a:4,s:"Per esempio i ceppi di E. coli che causano cistite si attaccano all'epitelio urinario con le fimbrie."},
{t:"b1b",k:"c",q:"Nella trasduzione ____ il fago trasferisce solo i geni vicini al punto in cui si era integrato (una parola).",a:["SPECIALIZZATA", "RISTRETTA"],s:"Nella trasduzione generalizzata invece può portare qualsiasi frammento del cromosoma."},
{t:"b1b",k:"c",q:"Le piccole molecole di DNA circolare extracromosomico dei batteri, spesso con geni di resistenza agli antibiotici, si chiamano ____.",a:["PLASMIDI", "PLASMIDE"],s:"Si replicano in modo autonomo e passano tra batteri con la coniugazione."},
{t:"b1b",k:"c",q:"Dopo la colorazione di Gram i batteri Gram-negativi appaiono di colore ____.",a:["ROSA", "ROSSO"],s:"Colorati dalla safranina; i Gram-positivi restano viola."},
{t:"b1c",k:"m",q:"Quale di questi compartimenti NON fa parte del sistema delle endomembrane?",o:["mitocondri", "reticolo endoplasmatico", "apparato di Golgi", "lisosomi", "involucro nucleare"],a:0,s:"I mitocondri hanno origine endosimbiotica e non scambiano vescicole con le endomembrane."},
{t:"b1c",k:"m",q:"I ribosomi del citosol di una cellula eucariotica hanno coefficiente di sedimentazione:",o:["70S", "80S", "60S", "55S", "90S"],a:1,s:"80S = 60S + 40S; 70S sono quelli batterici (e simili nei mitocondri)."},
{t:"b1c",k:"m",q:"Secondo l'ipotesi più accreditata, il nucleo e il reticolo endoplasmatico si sono formati per:",o:["endosimbiosi di un batterio", "invaginazione della membrana plasmatica", "fusione di due mitocondri", "gemmazione di virus", "condensazione del citoscheletro"],a:1,s:"Per questo l'involucro nucleare è in continuità con il reticolo, mentre mitocondri e cloroplasti hanno un'altra origine."},
{t:"b1c",k:"m",q:"Quale di queste NON è una prova dell'origine endosimbiotica dei mitocondri?",o:["la doppia membrana", "il DNA circolare proprio", "la loro formazione ex novo per gemmazione dal reticolo endoplasmatico", "la divisione per scissione", "la sensibilità dei loro ribosomi ad alcuni antibiotici"],a:2,s:"È falsa: i mitocondri nascono solo da mitocondri preesistenti, come i batteri."},
{t:"b1c",k:"m",q:"Le dimensioni tipiche di una cellula eucariotica animale sono:",o:["0,1–1 nm", "1–10 nm", "1–5 µm", "10–100 µm", "1–10 mm"],a:3,s:"Le cellule procariotiche misurano invece circa 1–5 µm."},
{t:"b1c",k:"m",q:"Si marca una proteina destinata alla secrezione e la si segue nel tempo. Il suo percorso è:",o:["Golgi → RE → lisosoma → nucleo", "nucleo → mitocondrio → membrana plasmatica", "citosol → perossisoma → membrana plasmatica", "RE ruvido → Golgi → vescicole → membrana plasmatica", "membrana plasmatica → endosoma → RE"],a:3,s:"È il percorso classico della via secretoria nel sistema delle endomembrane."},
{t:"b1c",k:"m",q:"Che cosa è stato necessario per passare dagli organismi unicellulari a quelli pluricellulari complessi?",o:["la perdita del DNA in alcune cellule", "la presenza di cloroplasti in tutte le cellule", "l'arresto delle divisioni cellulari", "un genoma diverso in ogni tessuto", "adesione stabile tra cellule, comunicazione e differenziamento"],a:4,s:"Le cellule hanno lo stesso genoma ma esprimono geni diversi."},
{t:"b1c",k:"m",q:"I cloroplasti derivano da batteri inglobati. Il loro antenato più probabile è:",o:["un cianobatterio", "un archeobatterio metanogeno", "un virus a DNA", "un fungo", "un alfa-proteobatterio"],a:0,s:"Gli alfa-proteobatteri sono invece gli antenati dei mitocondri."},
{t:"b1c",k:"m",q:"Quale struttura è presente nella cellula eucariotica ma NON in quella procariotica?",o:["i ribosomi", "l'involucro nucleare", "la membrana plasmatica", "il DNA", "il citoplasma"],a:1,s:"I procarioti hanno il DNA libero nel nucleoide."},
{t:"b1c",k:"c",q:"I mitocondri deriverebbero da un antico ____-proteobatterio (lettera greca scritta per esteso).",a:["ALFA", "ALPHA"],s:"Simile ai batteri aerobi attuali come le rickettsie."},
{t:"b1c",k:"c",q:"Il sistema delle ____ comprende involucro nucleare, reticolo endoplasmatico, Golgi, endosomi, lisosomi e membrana plasmatica.",a:["ENDOMEMBRANE"],s:"Compartimenti collegati da vescicole."},
{t:"b1c",k:"c",q:"La teoria endosimbiotica moderna è stata proposta e difesa dalla biologa Lynn ____.",a:["MARGULIS"],s:"Negli anni '60–'70 del Novecento."},
{t:"b1d",k:"m",q:"Glicogeno, amido e cellulosa sono tutti polimeri di:",o:["fruttosio", "ribosio", "glucosio", "galattosio", "amminoacidi"],a:2,s:"Cambia il tipo di legame glicosidico (α nel glicogeno e nell'amido, β nella cellulosa)."},
{t:"b1d",k:"m",q:"Quale lipide è il principale componente strutturale delle membrane biologiche?",o:["i trigliceridi", "le cere", "i carotenoidi", "i fosfolipidi", "gli acidi grassi liberi"],a:3,s:"Anfipatici: testa polare e code idrofobiche formano il doppio strato."},
{t:"b1d",k:"m",q:"La struttura secondaria delle proteine (α-elica, foglietto β) è stabilizzata soprattutto da:",o:["legami peptidici", "ponti disolfuro", "interazioni idrofobiche tra catene laterali", "legami fosfodiestere", "legami idrogeno tra i gruppi C=O e N–H dello scheletro"],a:4,s:"Primaria = sequenza; secondaria = legami H dello scheletro; terziaria = interazioni tra catene laterali."},
{t:"b1d",k:"m",q:"Un dominio proteico è:",o:["una porzione della proteina che si ripiega in modo indipendente e svolge una funzione propria", "la sequenza completa di amminoacidi", "il sito del ribosoma che lega l'mRNA", "un insieme di proteine identiche", "una modificazione post-traduzionale"],a:0,s:"Lo stesso dominio (es. di legame al DNA) può comparire in proteine diverse."},
{t:"b1d",k:"m",q:"Quale modificazione post-traduzionale aggiunge catene di zuccheri alle proteine, soprattutto nel RE e nel Golgi?",o:["fosforilazione", "glicosilazione", "acetilazione", "ubiquitinazione", "prenilazione"],a:1,s:"N-glicosilazione sull'asparagina nel RE, O-glicosilazione su serina/treonina nel Golgi."},
{t:"b1d",k:"m",q:"L'aggiunta di un gruppo lipidico (palmitoilazione, prenilazione, miristoilazione) a una proteina serve soprattutto a:",o:["portarla nel nucleo", "degradarla nel proteasoma", "ancorarla a una membrana", "renderla più solubile in acqua", "attivarne la trascrizione"],a:2,s:"Ras, per esempio, funziona solo se prenilata e ancorata alla membrana."},
{t:"b1d",k:"m",q:"Un enzima che rimuove l'ubiquitina da una proteina, sottraendola alla degradazione, è una:",o:["ubiquitina ligasi E3", "chinasi", "deacetilasi", "deubiquitinasi", "fosfatasi"],a:3,s:"Ogni modificazione reversibile ha l'enzima che la mette e quello che la toglie."},
{t:"b1d",k:"m",q:"Un filamento di DNA ha sequenza 5'-ATGC-3'. Il filamento complementare, scritto 5'→3', è:",o:["5'-TACG-3'", "5'-GCAT-3'", "5'-CGTA-3'", "5'-ATGC-3'", "5'-UACG-3'"],a:1,s:"Il complementare è 3'-TACG-5', che letto da 5' a 3' diventa GCAT."},
{t:"b1d",k:"m",q:"Quale di questi RNA è codificante?",o:["tRNA", "rRNA", "miRNA", "snRNA", "mRNA"],a:4,s:"Solo l'mRNA viene tradotto in proteina; gli altri funzionano come RNA."},
{t:"b1d",k:"m",q:"Le chinasi proteiche trasferiscono il fosfato dell'ATP sull'ossidrile di:",o:["serina, treonina e tirosina", "lisina, arginina e istidina", "glicina e alanina", "cisteina e metionina", "asparagina e glutammina"],a:0,s:"Sono gli unici amminoacidi con un –OH nella catena laterale."},
{t:"b1d",k:"c",q:"Il legame che unisce i nucleotidi in un filamento di DNA o di RNA si chiama legame ____.",a:["FOSFODIESTERE", "FOSFODIESTERICO"],s:"Unisce il 3'-OH di uno zucchero al fosfato in 5' del successivo."},
{t:"b1d",k:"c",q:"L'insieme delle reazioni che demoliscono molecole complesse liberando energia è il ____.",a:["CATABOLISMO"],s:"Esempio: glicolisi e respirazione cellulare."},
{t:"b1d",k:"c",q:"Il legame covalente tra due monosaccaridi si chiama legame ____.",a:["GLICOSIDICO", "O-GLICOSIDICO", "OGLICOSIDICO"],s:"Si forma per condensazione."},
{t:"b1d",k:"c",q:"Nella doppia elica la coppia guanina–citosina è unita da ____ legami idrogeno (numero).",a:["3", "TRE"],s:"A–T ne ha 2: le regioni ricche di GC sono più stabili."},
{t:"b2a",k:"m",q:"Un cromosoma con il centromero vicinissimo a un'estremità e un braccio p cortissimo si dice:",o:["metacentrico", "submetacentrico", "acrocentrico", "olocentrico", "dicentrico"],a:2,s:"Nell'uomo sono acrocentrici i cromosomi 13, 14, 15, 21 e 22."},
{t:"b2a",k:"m",q:"Nei cromosomi umani il DNA centromerico è formato soprattutto da:",o:["ripetizioni TTAGGG", "DNA satellite alfa ripetuto in tandem", "geni per l'rRNA", "sequenze Alu", "esoni delle globine"],a:1,s:"Unità di circa 171 bp ripetute migliaia di volte."},
{t:"b2a",k:"m",q:"Che cosa succede a un frammento di cromosoma privo di centromero (acentrico)?",o:["non viene replicato", "le sue estremità si fondono sempre in un anello", "non si aggancia al fuso e viene perso durante le divisioni", "viene trascritto di più", "diventa un plasmide"],a:2,s:"Senza centromero non si forma il cinetocore."},
{t:"b2a",k:"m",q:"A che cosa serve soprattutto la struttura protetta dei telomeri (ansa e proteine dedicate)?",o:["ad agganciare i microtubuli", "ad avviare la trascrizione", "a legare i ribosomi", "a evitare che le estremità siano riconosciute come rotture del DNA e fuse tra loro", "a replicare il DNA mitocondriale"],a:3,s:"Senza protezione la cellula ripara le estremità unendole, con cromosomi fusi."},
{t:"b2a",k:"m",q:"Il braccio corto di un cromosoma si indica con la lettera:",o:["q", "c", "s", "t", "p"],a:4,s:"Dal francese petit; il braccio lungo è q."},
{t:"b2a",k:"m",q:"Perché i cromosomi eucariotici hanno molte origini di replicazione?",o:["per replicare in tempi brevi DNA molto lunghi", "perché la DNA polimerasi lavora 3'→5'", "perché sono circolari", "perché non hanno telomeri", "per evitare la trascrizione"],a:0,s:"Con una sola origine la fase S durerebbe settimane."},
{t:"b2a",k:"m",q:"Una cellula umana in G1 contiene:",o:["23 cromosomi e 46 cromatidi", "46 cromosomi e 46 molecole di DNA", "46 cromosomi e 92 cromatidi", "92 cromosomi", "23 coppie di cromatidi fratelli"],a:1,s:"Prima della fase S ogni cromosoma è una sola molecola di DNA."},
{t:"b2a",k:"m",q:"Nel cariotipo umano i cromosomi acrocentrici sono:",o:["1, 2 e 3", "X e Y", "13, 14, 15, 21 e 22", "16, 17 e 18", "solo il 21"],a:2,s:"I loro bracci corti portano i geni dell'rRNA (regioni organizzatrici del nucleolo)."},
{t:"b2a",k:"c",q:"Il braccio lungo di un cromosoma si indica con la lettera ____.",a:["Q"],s:"Il corto è p."},
{t:"b2a",k:"c",q:"La sequenza ripetuta dei telomeri umani è 5'-____-3' (sei lettere).",a:["TTAGGG"],s:"Ripetuta per migliaia di basi."},
{t:"b2a",k:"c",q:"Un cromosoma con il centromero in posizione centrale e due bracci di uguale lunghezza si dice ____.",a:["METACENTRICO"],s:"Esempi: cromosomi 1 e 3."},
{t:"b2b",k:"m",q:"L'istone H1:",o:["fa parte dell'ottamero del nucleosoma", "acetila le lisine degli altri istoni", "metila le citosine", "lega il DNA linker e favorisce la fibra da 30 nm", "è presente solo nei procarioti"],a:3,s:"È l'istone «di collegamento», fuori dall'ottamero."},
{t:"b2b",k:"m",q:"Nei mammiferi la metilazione del DNA avviene soprattutto su:",o:["adenine nelle sequenze TATA", "guanine dei telomeri", "uracili dell'RNA", "timine nelle sequenze AT", "citosine nei dinucleotidi CpG"],a:4,s:"Promotori con isole CpG metilate sono silenziati."},
{t:"b2b",k:"m",q:"Le istone deacetilasi (HDAC) tendono a:",o:["compattare la cromatina e reprimere la trascrizione", "attivare la trascrizione", "metilare il DNA", "tagliare i nucleosomi", "esportare l'mRNA"],a:0,s:"Togliendo l'acetile le lisine tornano positive e stringono il DNA."},
{t:"b2b",k:"m",q:"I complessi di rimodellamento della cromatina (es. SWI/SNF):",o:["tagliano il DNA in frammenti", "usano l'energia dell'ATP per far scorrere, spostare o rimuovere i nucleosomi", "aggiungono il cappuccio all'mRNA", "sono RNA catalitici", "allungano i telomeri"],a:1,s:"Così rendono accessibili promotori ed enhancer."},
{t:"b2b",k:"m",q:"Le condensine:",o:["tengono uniti i cromatidi fratelli fino all'anafase", "degradano gli istoni", "compattano i cromosomi all'ingresso in mitosi organizzandoli in anse", "sono fattori di trascrizione", "acetilano l'istone H3"],a:2,s:"Sono complessi SMC ad anello come le coesine, ma con funzione diversa."},
{t:"b2b",k:"m",q:"Il corpo di Barr (X inattivo nelle cellule femminili) è un esempio di:",o:["eucromatina", "eterocromatina costitutiva", "nucleolo", "eterocromatina facoltativa", "DNA mitocondriale"],a:3,s:"Facoltativa: lo stesso cromosoma X è attivo in altre cellule."},
{t:"b2b",k:"m",q:"Perché l'acetilazione di una lisina istonica indebolisce il legame tra istone e DNA?",o:["aggiunge una carica positiva alla lisina", "rompe il legame peptidico", "rende il DNA positivo", "aggiunge un fosfato al DNA", "neutralizza la carica positiva della lisina, che attrae meno i fosfati del DNA"],a:4,s:"Il DNA è negativo: meno cariche positive sugli istoni vuol dire legame più lasco."},
{t:"b2b",k:"m",q:"Quale affermazione sull'epigenetica è corretta?",o:["le modificazioni si possono trasmettere alle cellule figlie senza cambiare la sequenza", "modifica la sequenza delle basi", "riguarda solo i procarioti", "è sempre irreversibile", "coincide con le mutazioni puntiformi"],a:0,s:"Metilazione del DNA e marchi istonici vengono ricopiati dopo la replicazione."},
{t:"b2b",k:"c",q:"Il tratto di DNA che collega un nucleosoma al successivo si chiama DNA ____.",a:["LINKER", "DI COLLEGAMENTO"],s:"Qui si lega l'istone H1."},
{t:"b2b",k:"c",q:"Le proteine che tengono uniti i cromatidi fratelli dopo la replicazione si chiamano ____.",a:["COESINE", "COESINA"],s:"Vengono tagliate dalla separasi in anafase."},
{t:"b2b",k:"c",q:"L'enzima che aggiunge gruppi metile alle citosine del DNA è la DNA ____.",a:["METILTRANSFERASI", "METILTRASFERASI", "METILASI"],s:"DNMT1 copia la metilazione sul filamento nuovo dopo la replicazione."},
{t:"b2b",k:"c",q:"La cromatina meno condensata, ricca di geni attivi, si chiama ____.",a:["EUCROMATINA"],s:"Al microscopio appare chiara."},
{t:"b2c",k:"m",q:"I geni delle globine sono un esempio di:",o:["sequenze ripetute in tandem", "famiglia genica nata per duplicazione", "microsatelliti", "retrovirus endogeni", "SINE"],a:1,s:"Cluster α (cromosoma 16) e β (cromosoma 11), espressi in momenti diversi dello sviluppo."},
{t:"b2c",k:"m",q:"Nell'uomo i geni per gli rRNA 18S, 5,8S e 28S sono:",o:["sul cromosoma Y", "solo nel DNA mitocondriale", "ripetuti in tandem centinaia di volte sui bracci corti degli acrocentrici", "in copia singola", "sparsi come elementi Alu"],a:2,s:"Servono molte copie per produrre tantissimi ribosomi."},
{t:"b2c",k:"m",q:"Gli elementi LINE (es. L1) si spostano nel genoma:",o:["con un meccanismo taglia-e-incolla a DNA", "solo durante la meiosi", "grazie alla telomerasi", "copiandosi tramite un RNA e una trascrittasi inversa codificata da loro stessi", "usando gli enzimi dei SINE"],a:3,s:"Sono retrotrasposoni autonomi."},
{t:"b2c",k:"m",q:"Gli elementi SINE come Alu sono detti «non autonomi» perché:",o:["non vengono trascritti", "si trovano solo nei mitocondri", "sono proteine", "si trovano solo nei centromeri", "non codificano una trascrittasi inversa e usano quella dei LINE"],a:4,s:"Sono brevi (circa 300 bp) e dipendono dai LINE per muoversi."},
{t:"b2c",k:"m",q:"I trasposoni a DNA si spostano:",o:["con una trasposasi che li taglia e li reinserisce altrove", "tramite un intermedio a RNA", "solo nei virus", "per coniugazione", "grazie alla primasi"],a:0,s:"Meccanismo taglia-e-incolla; nell'uomo sono quasi tutti inattivi."},
{t:"b2c",k:"m",q:"I retrovirus endogeni sono:",o:["virus che infettano solo i batteri", "resti di antiche infezioni retrovirali integrati nella linea germinale e trasmessi di generazione in generazione", "virus a DNA liberi nel citoplasma", "plasmidi umani", "geni per gli istoni"],a:1,s:"Sono circa l'8% del genoma umano."},
{t:"b2c",k:"m",q:"I minisatelliti (VNTR) differiscono dai microsatelliti (STR) perché:",o:["sono dispersi e non in tandem", "sono codificanti", "hanno unità ripetute più lunghe (circa 10–100 bp)", "si trovano solo sull'X", "hanno unità di 1 bp"],a:2,s:"Entrambi sono ripetuti in tandem e polimorfici."},
{t:"b2c",k:"m",q:"Circa quale frazione del genoma umano deriva da elementi mobili?",o:["1,5%", "10%", "circa 45%", "90%", "quasi nulla"],a:2,s:"LINE ≈ 17%, SINE ≈ 10%, retrovirus endogeni ≈ 8%, trasposoni a DNA ≈ 3%."},
{t:"b2c",k:"m",q:"Uno pseudogene è:",o:["un gene attivo duplicato", "un microsatellite", "un gene mitocondriale", "una copia di un gene che ha perso la funzione per mutazioni", "un tipo di RNA catalitico"],a:3,s:"Frequenti nelle famiglie geniche, per esempio tra le globine."},
{t:"b2c",k:"c",q:"Il genoma umano aploide contiene circa ____ mila geni che codificano proteine (numero).",a:["20", "VENTI"],s:"Su circa 3,1 miliardi di coppie di basi."},
{t:"b2c",k:"c",q:"Le sequenze Alu sono lunghe circa ____ coppie di basi (numero).",a:["300"],s:"Più di un milione di copie nel genoma."},
{t:"b2c",k:"c",q:"Le sequenze ripetute sparse in tutto il genoma, come LINE e SINE, si dicono ripetute ____ (una parola).",a:["INTERSPERSE", "DISPERSE", "INTERCALATE"],s:"Opposte alle ripetute in tandem."},
{t:"b3a",k:"m",q:"In E. coli la replicazione del cromosoma circolare parte da:",o:["migliaia di origini", "i telomeri", "il promotore lac", "una sola origine e procede in una sola direzione", "una sola origine (oriC) e procede in due direzioni"],a:4,s:"Due forcelle si muovono in direzioni opposte fino a incontrarsi."},
{t:"b3a",k:"m",q:"Negli eucarioti le origini di replicazione vengono riconosciute da:",o:["il complesso ORC", "la telomerasi", "l'RNA polimerasi II", "la DNA ligasi", "TFIID"],a:0,s:"ORC recluta poi l'elicasi MCM, che si attiva all'inizio della fase S."},
{t:"b3a",k:"m",q:"La correzione di bozze (proofreading) della DNA polimerasi è un'attività:",o:["esonucleasica 5'→3'", "esonucleasica 3'→5'", "endonucleasica", "di primasi", "elicasica"],a:1,s:"La polimerasi torna indietro di un passo e toglie il nucleotide sbagliato appena inserito."},
{t:"b3a",k:"m",q:"Le proteine SSB nella forcella di replicazione:",o:["sintetizzano i primer", "uniscono i frammenti di Okazaki", "tengono separati i filamenti singoli impedendo che si riappaino", "allungano i telomeri", "tagliano il DNA"],a:2,s:"Single-strand binding proteins."},
{t:"b3a",k:"m",q:"Esperimento di Meselson e Stahl: batteri cresciuti in ¹⁵N vengono trasferiti in ¹⁴N. Dopo DUE generazioni il DNA si distribuisce in:",o:["sola banda pesante", "sola banda intermedia", "metà banda intermedia e metà banda leggera", "sola banda leggera", "metà banda pesante e metà leggera"],a:2,s:"Le due eliche ibride si separano: ognuna dà un'elica ibrida e una tutta leggera."},
{t:"b3a",k:"m",q:"Le cellule somatiche umane in coltura smettono di dividersi dopo circa 50 divisioni. Il motivo principale è:",o:["la perdita dei centromeri", "un eccesso di telomerasi", "la mancanza di primasi", "l'accorciamento dei telomeri", "l'esaurimento dei ribosomi"],a:3,s:"Senescenza replicativa (limite di Hayflick)."},
{t:"b3a",k:"m",q:"Nei procarioti l'enzima che rimuove i primer di RNA e li sostituisce con DNA è:",o:["la DNA polimerasi III", "la primasi", "l'elicasi", "la telomerasi", "la DNA polimerasi I"],a:4,s:"Ha un'attività esonucleasica 5'→3'; la Pol III è la replicasi principale."},
{t:"b3a",k:"m",q:"Su quale filamento la DNA ligasi deve intervenire più volte?",o:["sul filamento ritardato", "sul filamento guida", "su entrambi allo stesso modo", "su nessuno dei due", "solo sull'RNA primer"],a:0,s:"Deve unire tutti i frammenti di Okazaki."},
{t:"b3a",k:"c",q:"I brevi tratti di DNA sintetizzati sul filamento ritardato si chiamano frammenti di ____.",a:["OKAZAKI"],s:"Circa 100–200 nucleotidi negli eucarioti."},
{t:"b3a",k:"c",q:"L'enzima che separa i due filamenti rompendo i legami idrogeno tra le basi è l'____.",a:["ELICASI", "DNA ELICASI"],s:"Usa l'energia dell'ATP."},
{t:"b3a",k:"c",q:"Il numero massimo di divisioni di una cellula somatica normale prima della senescenza si chiama limite di ____.",a:["HAYFLICK"],s:"Legato alla lunghezza dei telomeri."},
{t:"b3b",k:"m",q:"Un mRNA policistronico:",o:["contiene molti introni", "codifica più proteine una dopo l'altra, come negli operoni procariotici", "è tipico dei geni eucariotici", "ha più cappucci", "è un RNA non codificante"],a:1,s:"Gli mRNA eucariotici sono in genere monocistronici."},
{t:"b3b",k:"m",q:"Operone lac: lattosio presente E glucosio abbondante. La trascrizione è:",o:["massima", "nulla perché il repressore è legato", "bassa, perché il cAMP è basso e CAP non attiva", "massima perché il glucosio attiva CAP", "impossibile senza RNA polimerasi"],a:2,s:"Il repressore è staccato, ma senza CAP-cAMP la polimerasi lega male il promotore."},
{t:"b3b",k:"m",q:"Gli enhancer sono:",o:["sempre subito a monte della TATA box", "proteine attivatrici", "presenti solo nei procarioti", "sequenze in cis che legano attivatori e funzionano anche a grande distanza e in entrambi gli orientamenti", "codoni di inizio"],a:3,s:"Il DNA si ripiega e porta l'attivatore vicino al promotore."},
{t:"b3b",k:"m",q:"Nei batteri il fattore σ dell'RNA polimerasi serve a:",o:["terminare la trascrizione", "aggiungere il cappuccio", "fare lo splicing", "legare il lattosio", "riconoscere le sequenze −10 e −35 del promotore"],a:4,s:"Dopo l'inizio si stacca e la polimerasi prosegue da sola."},
{t:"b3b",k:"m",q:"Quale di questi è un esempio di controllo POST-TRADUZIONALE dell'espressione genica?",o:["fosforilazione di un enzima che lo attiva", "metilazione del promotore", "splicing alternativo", "blocco della traduzione da parte di un miRNA", "legame di un attivatore a un enhancer"],a:0,s:"Agisce sulla proteina già fatta."},
{t:"b3b",k:"m",q:"Nella trascrizione eucariotica, la fosforilazione della coda C-terminale (CTD) dell'RNA polimerasi II segna il passaggio:",o:["dall'allungamento alla traduzione", "dall'inizio all'allungamento", "dalla trascrizione alla replicazione", "dalla terminazione all'inizio", "dal nucleo al citosol"],a:1,s:"La fosforila TFIIH; la coda fosforilata recluta anche gli enzimi di capping e splicing."},
{t:"b3b",k:"m",q:"Un recettore per un ormone steroideo, dopo aver legato l'ormone:",o:["apre un canale per il Na⁺", "attiva una proteina G", "si lega a sequenze specifiche del DNA e regola la trascrizione", "viene subito degradato nel lisosoma", "fosforila tirosine sulla membrana"],a:2,s:"Le sequenze sono detti elementi di risposta all'ormone."},
{t:"b3b",k:"m",q:"Un silencer è:",o:["una proteina repressore", "un codone di stop", "un tipo di introne", "una sequenza in cis che, legando repressori, riduce la trascrizione", "la sequenza dell'mRNA che lega il ribosoma"],a:3,s:"È l'opposto dell'enhancer."},
{t:"b3b",k:"c",q:"Nell'operone lac la sequenza di DNA a cui si lega il repressore si chiama ____.",a:["OPERATORE"],s:"Si sovrappone al promotore e blocca la polimerasi."},
{t:"b3b",k:"c",q:"L'RNA polimerasi eucariotica che trascrive gli mRNA è la RNA polimerasi ____ (numero romano).",a:["II", "2", "DUE"],s:"Pol I fa gli rRNA grandi, Pol III tRNA e 5S."},
{t:"b3b",k:"c",q:"Nell'operone lac la molecola induttrice che stacca il repressore è l'____.",a:["ALLOLATTOSIO"],s:"Isomero del lattosio."},
{t:"b3c",k:"m",q:"Il segnale di poliadenilazione nel pre-mRNA eucariotico è la sequenza:",o:["TATAAA", "AUG", "UAA", "CCA", "AAUAAA"],a:4,s:"Il taglio avviene 10–30 nucleotidi più a valle e poi si aggiunge la poli-A."},
{t:"b3c",k:"m",q:"Gli introni nucleari più comuni iniziano e finiscono con:",o:["GU all'inizio e AG alla fine", "AG all'inizio e GU alla fine", "AUG all'inizio e UAA alla fine", "CCA all'inizio e AAA alla fine", "TATA all'inizio e AAUAAA alla fine"],a:0,s:"Regola GU–AG; U1 riconosce il sito al 5'."},
{t:"b3c",k:"m",q:"L'editing dell'mRNA dell'ApoB nell'intestino:",o:["aggiunge un introne", "trasforma una C in U creando un codone di stop e producendo l'ApoB-48", "elimina il cappuccio", "aggiunge la coda di poli-A", "fa tradurre l'mRNA nel nucleo"],a:1,s:"Nel fegato lo stesso mRNA non viene modificato e dà l'ApoB-100."},
{t:"b3c",k:"m",q:"Nel citoplasma la degradazione di molti mRNA inizia con:",o:["l'aggiunta di un secondo cappuccio", "lo splicing", "l'accorciamento della coda di poli-A (deadenilazione), seguito dalla rimozione del cappuccio", "la metilazione del DNA", "l'editing C→U"],a:2,s:"Senza poli-A e cappuccio le esonucleasi degradano l'mRNA."},
{t:"b3c",k:"m",q:"Che differenza c'è tra siRNA e miRNA?",o:["i miRNA sono proteine", "i siRNA sono lunghi circa 2000 nucleotidi", "solo i miRNA usano il complesso RISC", "i siRNA nascono da RNA a doppio filamento e, appaiati perfettamente, fanno tagliare il bersaglio; i miRNA nascono da precursori a forcina e spesso ne bloccano la traduzione", "i siRNA agiscono direttamente sul DNA"],a:3,s:"Entrambi sono lunghi circa 21–23 nucleotidi e usano Dicer e RISC."},
{t:"b3c",k:"m",q:"Come maturano i tRNA?",o:["con cappuccio e coda di poli-A", "con splicing alternativo obbligatorio", "con la traduzione nel nucleolo", "con l'editing C→U", "con taglio del precursore, aggiunta di CCA al 3' e modificazione di basi"],a:4,s:"Il CCA è il sito di attacco dell'amminoacido."},
{t:"b3c",k:"m",q:"Quale di questi è un ribozima?",o:["un introne di gruppo I capace di autosplicing", "la DNA ligasi", "l'istone H1", "la poli-A polimerasi", "l'amminoacil-tRNA sintetasi"],a:0,s:"Scoperto da Cech: un RNA che si taglia e si ricuce da solo."},
{t:"b3c",k:"m",q:"Dove avviene lo splicing del pre-mRNA e in che forma esce l'introne?",o:["nel citoplasma, in forma lineare", "nel nucleo, a forma di cappio (lariat)", "nel ribosoma, come anello chiuso da un legame peptidico", "nel nucleolo, come tRNA", "nel Golgi, glicosilato"],a:1,s:"L'introne viene poi aperto e degradato."},
{t:"b3c",k:"c",q:"La coda di poli-A viene aggiunta dall'enzima poli-A ____.",a:["POLIMERASI"],s:"Non usa uno stampo."},
{t:"b3c",k:"c",q:"Gli enzimi Drosha (nel nucleo) e ____ (nel citoplasma) tagliano i precursori dei microRNA.",a:["DICER"],s:"Il miRNA maturo entra poi nel complesso RISC."},
{t:"b3c",k:"c",q:"Il precursore degli rRNA trascritto nel nucleolo dalla RNA polimerasi I ha coefficiente di sedimentazione ____ S (numero).",a:["45"],s:"Viene tagliato in 18S, 5,8S e 28S."},
{t:"b3c",k:"c",q:"Il complesso proteico che, guidato da un miRNA, si lega all'mRNA bersaglio si chiama ____ (sigla).",a:["RISC"],s:"Contiene la proteina Argonauta."},
{t:"b3d",k:"m",q:"Nei procarioti la subunità minore del ribosoma trova il codone di inizio grazie alla sequenza:",o:["cappuccio 7-metilguanosina", "coda di poli-A", "Shine-Dalgarno", "TATA box", "AAUAAA"],a:2,s:"Si appaia all'rRNA 16S; negli eucarioti il ribosoma parte invece dal cappuccio."},
{t:"b3d",k:"m",q:"Il codone è 5'-ACG-3'. L'anticodone del tRNA che lo legge, scritto 5'→3', è:",o:["5'-UGC-3'", "5'-CGU-3'", "5'-ACG-3'", "5'-TGC-3'", "5'-GCA-3'"],a:1,s:"Appaiamento antiparallelo: 3'-UGC-5', cioè 5'-CGU-3'."},
{t:"b3d",k:"m",q:"La proprietà per cui il codice genetico è quasi lo stesso in batteri, piante e animali si chiama:",o:["degenerazione", "ambiguità", "sovrapposizione", "universalità", "vacillamento"],a:3,s:"Eccezioni minori nei mitocondri."},
{t:"b3d",k:"m",q:"Il fattore di allungamento eEF1A (EF-Tu nei batteri):",o:["riconosce i codoni di stop", "separa le subunità del ribosoma", "aggiunge l'ubiquitina", "forma il legame peptidico", "porta l'amminoacil-tRNA nel sito A usando GTP"],a:4,s:"eEF2 (EF-G) fa poi avanzare il ribosoma di un codone."},
{t:"b3d",k:"m",q:"La quantità di ferro regola la traduzione della ferritina tramite proteine che legano una forcina dell'mRNA situata:",o:["nella 5'UTR", "nella regione codificante", "nella coda di poli-A", "nel promotore del gene", "nella proteina matura"],a:0,s:"Con poco ferro le proteine IRP bloccano l'inizio della traduzione: esempio di funzione regolatoria delle UTR."},
{t:"b3d",k:"m",q:"Le chaperonine (es. Hsp60):",o:["degradano le proteine", "formano una camera in cui la proteina si ripiega isolata dal citosol", "sintetizzano amminoacidi", "trascrivono il DNA", "aggiungono zuccheri alle proteine"],a:1,s:"Usano ATP; Hsp70 invece lega le catene nascenti."},
{t:"b3d",k:"m",q:"Malattie da prioni e malattia di Alzheimer hanno in comune:",o:["una mutazione del DNA mitocondriale", "un difetto di splicing", "proteine mal ripiegate che formano aggregati (amiloide)", "un'infezione batterica", "l'assenza di ribosomi"],a:2,s:"Le proteine misfolded ricche di foglietti β si aggregano e danneggiano i neuroni."},
{t:"b3d",k:"m",q:"Le proteine SUMO:",o:["sono enzimi del proteasoma", "sono subunità del ribosoma", "sono fattori di rilascio", "sono proteine simili all'ubiquitina che si legano covalentemente ad altre proteine cambiandone localizzazione o attività", "sono chaperon del reticolo"],a:3,s:"La sumoilazione usa enzimi E1-E2-E3 come l'ubiquitina, ma di solito non porta alla degradazione."},
{t:"b3d",k:"m",q:"Quanti dei 64 codoni codificano amminoacidi?",o:["20", "60", "61", "63", "64"],a:2,s:"3 sono di stop."},
{t:"b3d",k:"c",q:"I fattori che riconoscono i codoni di stop e liberano la catena polipeptidica si chiamano fattori di ____.",a:["RILASCIO", "TERMINAZIONE"],s:"eRF1 negli eucarioti."},
{t:"b3d",k:"c",q:"Il sito del ribosoma in cui entra l'amminoacil-tRNA è il sito ____ (una lettera).",a:["A"],s:"Poi passa in P e infine in E."},
{t:"b4a",k:"m",q:"La sostituzione di una A con una G in un gene è una:",o:["transversione", "delezione", "frameshift", "inserzione", "transizione"],a:4,s:"Purina → purina."},
{t:"b4a",k:"m",q:"Il codone GAA (glutammato) mutato in GAG (glutammato) dà una mutazione:",o:["silente", "missenso", "nonsenso", "frameshift", "per espansione"],a:0,s:"Grazie alla degenerazione del codice l'amminoacido non cambia."},
{t:"b4a",k:"m",q:"Nell'anemia falciforme, nel gene della β-globina il codone GAG (glutammato) diventa GTG (valina). È una mutazione:",o:["silente", "missenso", "nonsenso", "frameshift", "per espansione di triplette"],a:1,s:"Cambia un solo amminoacido (transversione A→T)."},
{t:"b4a",k:"m",q:"Nelle malattie da espansione di triplette, l'anticipazione consiste in:",o:["guarigione spontanea nelle generazioni successive", "trasmissione solo per via materna", "malattia più precoce e grave nelle generazioni successive per l'allungamento della ripetizione", "una mutazione silente", "la perdita dei telomeri"],a:2,s:"Più ripetizioni = esordio più precoce."},
{t:"b4a",k:"m",q:"Il sistema di riparazione dei mismatch (MMR) corregge:",o:["rotture a doppio filamento", "dimeri di timina", "telomeri troppo corti", "basi appaiate male sfuggite alla correzione di bozze della polimerasi", "legami crociati tra proteine"],a:3,s:"Riconosce il filamento nuovo e lo corregge; difettoso nella sindrome di Lynch."},
{t:"b4a",k:"m",q:"La riparazione NHEJ (unione delle estremità non omologhe):",o:["è precisa e usa il cromatidio fratello", "ripara solo i dimeri di timina", "avviene solo in fase S", "usa l'RNA come stampo", "è rapida ma può perdere o aggiungere nucleotidi"],a:4,s:"Funziona in tutte le fasi, soprattutto G1."},
{t:"b4a",k:"m",q:"Un uracile comparso nel DNA per deaminazione di una citosina viene rimosso da:",o:["BER, che inizia con una DNA glicosilasi", "NER", "ricombinazione omologa", "NHEJ", "telomerasi"],a:0,s:"La glicosilasi stacca la base, poi si toglie lo zucchero e si risintetizza."},
{t:"b4a",k:"m",q:"Quale di queste è una mutazione cromosomica strutturale e non genica?",o:["transizione", "inversione di un segmento di cromosoma", "frameshift", "mutazione silente", "mutazione nonsenso"],a:1,s:"Riguarda un tratto visibile del cromosoma."},
{t:"b4a",k:"m",q:"L'inserzione di 3 nucleotidi in una sequenza codificante, senza creare uno stop, provoca di solito:",o:["uno spostamento della cornice di lettura", "sempre una proteina tronca", "l'aggiunta di un amminoacido senza cambiare la cornice di lettura", "la perdita del promotore", "la duplicazione del gene"],a:2,s:"3 è multiplo di 3: la lettura a valle resta la stessa."},
{t:"b4a",k:"c",q:"Nella corea di Huntington la tripletta che si espande è ____.",a:["CAG"],s:"Codifica glutammina: tratti di poliglutammina tossici."},
{t:"b4a",k:"c",q:"Lo xeroderma pigmentoso è dovuto a un difetto della riparazione per escissione di ____.",a:["NUCLEOTIDI", "NUCLEOTIDE"],s:"NER: non si rimuovono i dimeri di timina da UV."},
{t:"b4a",k:"c",q:"Nella sindrome dell'X fragile la tripletta che si espande è ____.",a:["CGG"],s:"Nella regione 5' non tradotta del gene FMR1, che viene metilato e spento."},
{t:"b4b",k:"m",q:"Bocca di leone rossa (RR) × bianca (BB) dà una F1 rosa. Incrociando due F1 rosa, la F2 sarà:",o:["3 rosse : 1 bianca", "tutte rosa", "9:3:3:1", "1 rossa : 2 rosa : 1 bianca", "1 rossa : 1 bianca"],a:3,s:"Dominanza incompleta: genotipi e fenotipi coincidono (1:2:1)."},
{t:"b4b",k:"m",q:"Testcross: un individuo a fenotipo dominante × aa dà metà figli dominanti e metà recessivi. Il suo genotipo è:",o:["AA", "aa", "non determinabile", "AaBb", "Aa"],a:4,s:"Se fosse AA i figli sarebbero tutti dominanti."},
{t:"b4b",k:"m",q:"AaBb × aabb, geni indipendenti: probabilità di un figlio aabb?",o:["1/16", "1/4", "1/2", "3/16", "9/16"],a:1,s:"1/2 (aa) × 1/2 (bb) = 1/4."},
{t:"b4b",k:"m",q:"Epistasi recessiva (es. colore del mantello nei labrador): da AaBb × AaBb il rapporto fenotipico tipico è:",o:["9:3:4", "9:3:3:1", "3:1", "1:2:1", "15:1"],a:0,s:"I 4/16 omozigoti ee non depositano pigmento, qualunque sia l'altro gene."},
{t:"b4b",k:"m",q:"Due geni sullo stesso cromosoma danno il 12% di ricombinanti. Sulla mappa genetica distano:",o:["1,2 cM", "6 cM", "12 cM", "24 cM", "88 cM"],a:2,s:"1% di ricombinazione = 1 centiMorgan."},
{t:"b4b",k:"m",q:"Un genitore ha gruppo AB, l'altro gruppo 0. Quali gruppi possono avere i figli?",o:["solo AB", "A o B", "A, B, AB o 0", "solo 0", "AB o 0"],a:1,s:"IᴬIᴮ × ii → Iᴬi (A) o Iᴮi (B), ciascuno 1/2."},
{t:"b4b",k:"m",q:"A differenza di una mappa genetica, una mappa fisica esprime le distanze:",o:["in centiMorgan", "in frequenze di ricombinazione", "in coppie di basi, cioè posizioni reali sul DNA", "in numero di generazioni", "in percentuale di penetranza"],a:2,s:"Le due mappe hanno lo stesso ordine dei geni ma scale diverse."},
{t:"b4b",k:"m",q:"Malattia autosomica dominante con penetranza dell'80%. Un genitore è eterozigote, l'altro sano. Probabilità che un figlio manifesti la malattia?",o:["20%", "40%", "50%", "80%", "100%"],a:1,s:"1/2 (eredita l'allele) × 0,8 (lo manifesta) = 0,4."},
{t:"b4b",k:"m",q:"L'altezza nell'uomo, con distribuzione «a campana» nella popolazione, è un esempio di carattere:",o:["mendeliano semplice", "legato all'Y", "mitocondriale", "poligenico (quantitativo) influenzato dall'ambiente", "codominante"],a:3,s:"Molti geni con piccoli effetti additivi più l'ambiente."},
{t:"b4b",k:"m",q:"Prader-Willi e Angelman sono causate dalla delezione della stessa regione del cromosoma 15. Si distinguono per:",o:["il sesso del figlio", "l'età della madre", "il numero di cromosomi", "la presenza di triplette espanse", "l'origine paterna o materna della delezione (imprinting genomico)"],a:4,s:"Delezione sul 15 paterno → Prader-Willi; sul 15 materno → Angelman."},
{t:"b4b",k:"c",q:"Una persona con due alleli mutati diversi dello stesso gene è un eterozigote ____.",a:["COMPOSTO"],s:"Frequente nella fibrosi cistica."},
{t:"b4b",k:"c",q:"Un gene che maschera l'effetto di un altro gene situato in un locus diverso si dice ____ (aggettivo).",a:["EPISTATICO"],s:"Quello mascherato è ipostatico."},
{t:"b4b",k:"c",q:"Il diverso grado di gravità con cui lo stesso genotipo si manifesta nei portatori si chiama ____.",a:["ESPRESSIVITÀ", "ESPRESSIVITA"],s:"Da non confondere con la penetranza (sì/no)."},
{t:"b4b",k:"c",q:"Da Aa × Aa, la probabilità che un figlio con fenotipo dominante sia eterozigote è ____ (frazione).",a:["2/3"],s:"Tra i dominanti (1 AA + 2 Aa) gli eterozigoti sono 2 su 3."},
{t:"b4c",k:"m",q:"Il bandeggio G si ottiene trattando i cromosomi metafasici con tripsina e colorandoli con:",o:["Giemsa", "cristalvioletto", "safranina", "Lugol", "blu di metilene a caldo"],a:0,s:"Le bande scure sono ricche di AT e povere di geni."},
{t:"b4c",k:"m",q:"La trisomia 21 libera (circa il 95% dei casi) deriva soprattutto da:",o:["una traslocazione robertsoniana ereditata", "una non disgiunzione meiotica, più spesso nella meiosi I materna", "una mutazione puntiforme", "un'espansione di triplette", "una delezione del cromosoma 21"],a:1,s:"Il rischio cresce con l'età materna."},
{t:"b4c",k:"m",q:"Una persona ha 46 cromosomi: uno è la fusione di un 14 con un 21, e ci sono anche due cromosomi 21 liberi. Ha:",o:["un cariotipo normale", "una monosomia 14", "una trisomia 21 da traslocazione", "una triploidia", "una sindrome di Turner"],a:2,s:"Tre copie del 21 (due libere + una fusa): sindrome di Down da traslocazione, circa il 4% dei casi."},
{t:"b4c",k:"m",q:"Un portatore sano di traslocazione robertsoniana 14;21 ha in genere:",o:["47 cromosomi", "45 cromosomi", "46 cromosomi", "69 cromosomi", "92 cromosomi"],a:1,s:"Due cromosomi sono fusi in uno: materiale completo ma un centromero in meno."},
{t:"b4c",k:"m",q:"Il cariotipo 45,X corrisponde a:",o:["sindrome di Klinefelter", "sindrome di Down", "sindrome di Patau", "sindrome di Turner", "triplo X"],a:3,s:"Femmina bassa, con gonadi non funzionanti."},
{t:"b4c",k:"m",q:"Una cellula umana con 69 cromosomi è:",o:["trisomica", "monosomica", "tetraploide", "aneuploide per un solo cromosoma", "triploide"],a:4,s:"3n = 69: poliploidia, non vitale."},
{t:"b4c",k:"m",q:"Il cromosoma Philadelphia della leucemia mieloide cronica è:",o:["una traslocazione reciproca tra i cromosomi 9 e 22", "una delezione del 5p", "un'inversione del cromosoma 9", "una trisomia del 22", "una traslocazione robertsoniana"],a:0,s:"Forma il gene di fusione BCR-ABL."},
{t:"b4c",k:"m",q:"La sindrome del cri du chat è causata da:",o:["una trisomia del 5", "la delezione del braccio corto del cromosoma 5", "una traslocazione 9;22", "una monosomia X", "una duplicazione del 21"],a:1,s:"Notazione 5p−."},
{t:"b4c",k:"m",q:"Per preparare un cariotipo le cellule in divisione vengono bloccate in metafase con:",o:["tripsina", "penicillina", "colchicina (o colcemid)", "insulina", "actinomicina D"],a:2,s:"Impedisce la formazione del fuso."},
{t:"b4c",k:"c",q:"La notazione del cariotipo di una femmina con trisomia 18 è 47,XX,____.",a:["+18"],s:"Sindrome di Edwards."},
{t:"b4c",k:"c",q:"La sindrome di Patau è la trisomia del cromosoma ____ (numero).",a:["13", "TREDICI"],s:"Grave, spesso letale nel primo anno."},
{t:"b4c",k:"c",q:"Un'inversione che comprende il centromero si dice ____.",a:["PERICENTRICA"],s:"Se non lo comprende è paracentrica."},
{t:"b4d",k:"m",q:"Padre affetto da una malattia dominante legata all'X, madre sana. I figli saranno:",o:["tutti sani", "metà malati in entrambi i sessi", "tutti i maschi malati", "tutte le figlie malate e nessun figlio maschio malato", "solo i maschi malati"],a:3,s:"Il padre dà il suo X a tutte le figlie e l'Y a tutti i figli maschi."},
{t:"b4d",k:"m",q:"Padre emofilico (XʰY) e madre non portatrice: probabilità che una figlia sia portatrice?",o:["0", "1/4", "1/2", "3/4", "1"],a:4,s:"Ogni figlia riceve l'unico X del padre, quello mutato."},
{t:"b4d",k:"m",q:"Due genitori sani hanno un figlio con fibrosi cistica. Probabilità che un loro figlio SANO sia portatore?",o:["1/4", "1/2", "2/3", "3/4", "1"],a:2,s:"Tra i sani (1 AA + 2 Aa) i portatori sono 2 su 3."},
{t:"b4d",k:"m",q:"Un carattere compare in ogni generazione, colpisce maschi e femmine in ugual misura e passa anche da padre a figlio maschio. La modalità più probabile è:",o:["autosomica recessiva", "recessiva legata all'X", "mitocondriale", "legata all'Y", "autosomica dominante"],a:4,s:"L'Y non colpirebbe le femmine; l'X non passa da padre a figlio."},
{t:"b4d",k:"m",q:"Un carattere legato all'Y:",o:["passa dal padre a tutti i figli maschi e mai alle figlie", "colpisce maschi e femmine", "passa dalla madre a tutti i figli", "salta generazioni nelle femmine portatrici", "è recessivo nelle femmine"],a:0,s:"Le femmine non hanno l'Y."},
{t:"b4d",k:"m",q:"Un uomo con una malattia mitocondriale ha figli con una donna sana. Quanti figli saranno affetti?",o:["tutti", "nessuno", "metà", "solo i maschi", "solo le femmine"],a:1,s:"I mitocondri dello spermatozoo non vengono trasmessi."},
{t:"b4d",k:"m",q:"In un albero genealogico una doppia linea orizzontale tra i due genitori indica:",o:["divorzio", "gemelli", "consanguineità", "adozione", "portatore sano"],a:2,s:"Aumenta il rischio di malattie autosomiche recessive."},
{t:"b4d",k:"m",q:"Una donna sana il cui padre era daltonico sposa un uomo sano. Probabilità che un loro figlio maschio sia daltonico?",o:["0", "1/4", "1/2", "1", "1/8"],a:2,s:"La donna è portatrice obbligata (ha l'X del padre): ogni figlio maschio ha 1/2 di riceverlo."},
{t:"b4d",k:"m",q:"Una donna portatrice di daltonismo e un uomo sano aspettano un figlio di sesso non ancora noto. Probabilità che sia un maschio daltonico?",o:["1/2", "1/8", "1/4", "0", "3/4"],a:2,s:"1/2 (maschio) × 1/2 (riceve l'X mutato) = 1/4."},
{t:"b4d",k:"m",q:"Malattia autosomica dominante: un genitore malato eterozigote e uno sano hanno due figli. Probabilità che siano entrambi sani?",o:["1/2", "1/4", "3/4", "1/8", "0"],a:1,s:"Eventi indipendenti: 1/2 × 1/2."},
{t:"b4d",k:"c",q:"La presenza nella stessa cellula di mitocondri normali e mitocondri mutati si chiama ____.",a:["ETEROPLASMIA"],s:"Spiega la gravità variabile delle malattie mitocondriali."},
{t:"b4d",k:"c",q:"Negli alberi genealogici i maschi sono rappresentati con un ____.",a:["QUADRATO"],s:"Le femmine con un cerchio."},
{t:"b4d",k:"c",q:"Un carattere recessivo legato all'X non viene mai trasmesso da padre a figlio ____.",a:["MASCHIO"],s:"Il padre passa ai figli maschi l'Y."}
);
BIO_PT.push(
P("b1","b1b","Quale di questi organismi è un procariote?",["un lievito", "un'ameba", "un fungo", "un batterio", "un'alga verde"],3,"I batteri non hanno nucleo delimitato da membrana.",["Il lievito è un fungo unicellulare eucariote.", "L'ameba è un protozoo eucariote.", "I funghi sono eucarioti.", "", "Le alghe verdi sono eucarioti con cloroplasti."]),
P("b1","b1d","Le proteine sono formate da catene di:",["nucleotidi", "acidi grassi", "monosaccaridi", "basi azotate", "amminoacidi"],4,"Gli amminoacidi sono uniti da legami peptidici.",["I nucleotidi formano DNA e RNA.", "Gli acidi grassi formano i lipidi.", "I monosaccaridi formano i polisaccaridi.", "Le basi azotate sono parti dei nucleotidi.", ""]),
P("b2","b2a","I cromosomi sessuali di un maschio umano sono:",["XX", "XY", "YY", "X0", "XXY"],1,"La femmina è XX, il maschio XY.",["XX è il corredo femminile.", "", "YY non è vitale: serve almeno un X.", "X0 è la sindrome di Turner (fenotipo femminile).", "XXY è la sindrome di Klinefelter."]),
P("b2","b2b","Nel nucleo l'insieme di DNA e proteine si chiama:",["cromatina", "citoplasma", "nucleolo", "ribosoma", "involucro nucleare"],0,"Si condensa nei cromosomi durante la divisione.",["", "Il citoplasma è fuori dal nucleo.", "Il nucleolo è la zona dove si fanno i ribosomi.", "Il ribosoma è fatto di RNA e proteine e sintetizza proteine.", "L'involucro è la doppia membrana che circonda il nucleo."]),
P("b3","b3a","Prima che una cellula si divida, il suo DNA deve essere:",["tradotto in proteine", "trasformato in RNA", "duplicato", "eliminato", "tagliato a metà"],2,"Ogni cellula figlia deve ricevere una copia completa.",["La traduzione riguarda l'mRNA, non il DNA.", "È la trascrizione, che non serve a dividersi.", "", "Senza DNA le cellule figlie non vivrebbero.", "Ogni figlia avrebbe metà dei geni."]),
P("b3","b3d","Gli amminoacidi diversi che formano le proteine sono:",["4", "64", "2", "20", "100"],3,"Combinati in sequenze diverse danno tutte le proteine.",["4 sono le basi del DNA.", "64 sono i codoni.", "Troppo pochi per tutte le proteine.", "", "Valore inventato."]),
P("b4","b4b","Il fenotipo di un individuo è:",["l'insieme dei suoi geni", "l'insieme delle sue caratteristiche osservabili", "un tipo di cromosoma", "una mutazione", "un gamete"],1,"Dipende dal genotipo e dall'ambiente.",["Questo è il genotipo.", "", "Il cromosoma è una struttura del nucleo.", "La mutazione cambia il DNA, non è il fenotipo.", "Il gamete è una cellula sessuale."]),
P("b4","b4a","Una mutazione è:",["una malattia infettiva", "un tipo di cellula", "una proteina", "un ormone", "un cambiamento della sequenza del DNA"],4,"Può essere innocua, dannosa o (raramente) utile.",["Le malattie infettive sono causate da microbi.", "Non è una cellula.", "Può cambiare una proteina, ma non è una proteina.", "Gli ormoni sono messaggeri chimici.", ""])
);
{const T=BIO_TOPICS.find(t=>t.id==="b1a");
T.sp.push("L'albero della vita ricostruito dalle sequenze dell'rRNA ha alla base un antenato comune universale (LUCA) da cui si separano Batteri e Archei; gli Eucarioti sono più vicini agli Archei. Tutti i viventi condividono lo stesso codice genetico, il DNA come archivio, le membrane fosfolipidiche e l'ATP come moneta energetica: è la prova di un'origine comune. I virus non entrano nell'albero perché non sono cellule.");
T.sp.push("Le classi di virus animali si distinguono per il genoma e per come producono l'mRNA (Baltimore): virus a DNA a doppio filamento (herpes, adenovirus), a DNA a singolo filamento (parvovirus), a RNA a doppio filamento (rotavirus), a RNA a singolo filamento positivo, che fa già da mRNA (poliovirus, coronavirus), a RNA a singolo filamento negativo, che deve portare con sé una RNA polimerasi RNA-dipendente (influenza, morbillo), retrovirus a RNA che passano per il DNA (HIV) e virus a DNA con trascrittasi inversa (epatite B).");
T.sp.push("Entrata e uscita da una cellula animale. Il virus si lega a un recettore specifico (HIV: CD4), che decide quali cellule può infettare (tropismo). I virus con involucro entrano per fusione diretta con la membrana plasmatica o per endocitosi seguita da fusione con la membrana dell'endosoma; i virus nudi entrano per endocitosi e rompono l'endosoma. Escono per lisi della cellula (soprattutto virus nudi) o per gemmazione: il capside si avvolge in un pezzo di membrana plasmatica ricca di glicoproteine virali, spesso senza uccidere subito la cellula.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b1b");
T.sp.push("La colorazione di Gram ha quattro passaggi: cristalvioletto (tutti viola), Lugol (fissa il colorante formando un complesso con lo iodio), decolorazione con alcol o acetone, safranina (colorante di contrasto rosso). Il peptidoglicano spesso dei Gram-positivi trattiene il complesso e resta viola; nei Gram-negativi l'alcol scioglie la membrana esterna, il sottile peptidoglicano non trattiene il viola e la safranina li colora di rosa. Tra le due membrane dei Gram-negativi c'è lo spazio periplasmatico; la membrana esterna ha porine e, nel foglietto esterno, l'LPS.");
T.sp.push("Caratteristiche dei tre trasferimenti orizzontali. Trasformazione: solo i batteri «competenti» assorbono DNA libero rilasciato da batteri morti (esperimento di Griffith sui pneumococchi). Coniugazione: un batterio F⁺, che ha il plasmide F, costruisce il pilo sessuale e trasferisce una copia del plasmide a un F⁻, che diventa F⁺; se il plasmide F è integrato nel cromosoma (ceppo Hfr) si trasferiscono anche geni cromosomici. Trasduzione: generalizzata, quando un fago litico impacchetta per errore un pezzo qualsiasi del DNA batterico; specializzata, quando un profago, staccandosi male, porta con sé i geni vicini al suo sito di integrazione. L'importanza biologica è enorme: diffusione rapida di resistenze agli antibiotici e di fattori di virulenza tra specie diverse.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b1c");
T.sp.push("Come è nata la cellula eucariotica? Un antenato vicino agli Archei avrebbe sviluppato pieghe della membrana plasmatica che, staccandosi e circondando il DNA, avrebbero dato l'involucro nucleare e il reticolo endoplasmatico: per questo il lume del reticolo è continuo con lo spazio tra le due membrane nucleari e topologicamente equivale all'esterno della cellula. In seguito una cellula ospite avrebbe inglobato un alfa-proteobatterio aerobio (antenato dei mitocondri) e, nella linea delle piante, un cianobatterio (antenato dei cloroplasti). Nel tempo molti geni dell'endosimbionte sono passati al nucleo: oggi la maggior parte delle proteine mitocondriali è codificata dal DNA nucleare e importata.");
T.sp.push("Dagli organismi unicellulari ai pluricellulari. Le colonie (come Volvox) mostrano i primi passi: cellule unite che si dividono i compiti. Negli organismi complessi servono molecole di adesione (caderine, integrine), matrice extracellulare, giunzioni e segnali tra cellule, e soprattutto il differenziamento: lo stesso genoma viene letto in modo diverso, così una cellula diventa neurone e un'altra epatocita. La specializzazione porta anche alla separazione tra linea germinale (gameti) e linea somatica.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b1d");
T.sp.push("Zuccheri e carboidrati. I monosaccaridi (glucosio, fruttosio, galattosio, ribosio e desossiribosio) si uniscono con legami glicosidici in disaccaridi (saccarosio, lattosio, maltosio) e polisaccaridi: amido (riserva delle piante), glicogeno (riserva degli animali, molto ramificato, in fegato e muscoli), cellulosa (struttura delle pareti vegetali, con legami β che non sappiamo digerire). Catene di zuccheri legate a proteine e lipidi formano il glicocalice.");
T.sp.push("Lipidi: molecole poco solubili in acqua. I trigliceridi (glicerolo + 3 acidi grassi) sono riserva di energia; i fosfolipidi, anfipatici, formano il doppio strato delle membrane; gli steroidi (colesterolo, ormoni steroidei) hanno quattro anelli fusi; ci sono poi glicolipidi e sfingolipidi delle membrane. Gli acidi grassi saturi hanno catene diritte, gli insaturi hanno doppi legami che piegano la catena e rendono la membrana più fluida.");
T.sp.push("Proteine. Ogni amminoacido ha un carbonio α con un gruppo amminico, un carbossile e una catena laterale (R) diversa per ognuno dei 20. Il legame peptidico unisce il carbossile di uno all'amminico del successivo (condensazione) e la catena ha un'estremità N-terminale e una C-terminale. Struttura primaria: sequenza; secondaria: α-eliche e foglietti β stabilizzati da legami idrogeno dello scheletro; terziaria: ripiegamento 3D per interazioni tra catene laterali (idrofobiche, ioniche, idrogeno, ponti disolfuro); quaternaria: più catene insieme (emoglobina: 2α + 2β).");
T.sp.push("Oltre a fosforilazione, ubiquitinazione e acetilazione, due modificazioni post-traduzionali importanti sono la glicosilazione e l'aggiunta di lipidi. La glicosilazione aggiunge oligosaccaridi: sull'asparagina nel reticolo (N-glicosilazione) o su serina e treonina nel Golgi (O-glicosilazione); aiuta il ripiegamento, protegge dalle proteasi e forma segnali di riconoscimento sulla superficie. L'aggiunta di lipidi (miristoilazione, palmitoilazione, prenilazione, ancora GPI) aggancia le proteine alle membrane: Ras e le proteine G funzionano solo se ancorate.");
T.sp.push("Nucleotidi e RNA. Un nucleotide è formato da uno zucchero a 5 atomi di carbonio (desossiribosio nel DNA, ribosio nell'RNA), una base azotata (purine: adenina e guanina; pirimidine: citosina, timina nel DNA, uracile nell'RNA) e uno o più fosfati. I nucleotidi si legano con legami fosfodiestere 5'→3'. L'RNA è di solito a singolo filamento ma si ripiega su sé stesso con tratti appaiati (forcine), che gli danno forme e funzioni diverse: messaggero (mRNA), strutturale e catalitico (rRNA), adattatore (tRNA), regolatore (miRNA, lncRNA), dello splicing (snRNA). ATP, GTP, NAD⁺ e coenzima A sono nucleotidi o derivati, a ricordare che i nucleotidi servono anche al metabolismo energetico.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b2a");
T.sp.push("Il DNA centromerico umano è formato da DNA satellite alfa: un'unità di circa 171 bp ripetuta in tandem migliaia di volte. Il centromero però è definito soprattutto in modo epigenetico, da nucleosomi che contengono una variante dell'istone H3 (CENP-A), su cui si costruisce il cinetocore. Il DNA telomerico è formato da ripetizioni TTAGGG che terminano con un'estremità 3' a singolo filamento; questa si ripiega e si infila nella doppia elica formando un'ansa protetta da un complesso di proteine (shelterina). Così le estremità non vengono scambiate per rotture del DNA e non si fondono tra loro.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b2b");
T.sp.push("Il rimodellamento della cromatina è svolto da grandi complessi che usano l'energia dell'ATP (famiglia SWI/SNF e altre) per far scorrere i nucleosomi lungo il DNA, staccarli o sostituire gli istoni con varianti: così un promotore coperto da un nucleosoma può diventare accessibile ai fattori di trascrizione. Le modificazioni delle code degli istoni (acetilazione, metilazione, fosforilazione, ubiquitinazione) formano un «codice» letto da proteine con domini specifici: per esempio i bromodomini riconoscono le lisine acetilate e reclutano complessi che attivano la trascrizione.");
T.sp.push("Coesine e condensine sono complessi ad anello della famiglia SMC. Le coesine abbracciano i due cromatidi fratelli dalla fase S fino all'anafase; le condensine, attivate all'ingresso in mitosi, raccolgono la fibra di cromatina in anse e la ripiegano fino a formare il compatto cromosoma metafasico, che può così essere separato senza aggrovigliarsi. La metilazione del DNA viene mantenuta dopo ogni replicazione da una DNA metiltransferasi di mantenimento che riconosce le CpG emimetilate: per questo lo stato epigenetico si eredita nelle cellule figlie.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b2c");
T.sp.push("Gli elementi mobili del DNA (trasposoni) sono sequenze capaci di spostarsi o copiarsi in altri punti del genoma. I trasposoni a DNA usano una trasposasi con meccanismo «taglia e incolla». I retrotrasposoni si copiano tramite un intermedio a RNA e una trascrittasi inversa («copia e incolla»), quindi si moltiplicano: comprendono LINE (autonomi), SINE (non autonomi) e retrotrasposoni con lunghe ripetizioni terminali (LTR), tra cui i retrovirus endogeni, resti di infezioni retrovirali entrate nella linea germinale milioni di anni fa. Quasi tutti oggi sono inattivi, ma qualche nuovo inserimento di L1 o Alu in un gene può causare malattie (per esempio alcuni casi di emofilia).");
T.sp.push("Nelle famiglie geniche, accanto ai geni funzionanti, ci sono spesso pseudogeni: copie che hanno accumulato mutazioni e non producono più una proteina. Le duplicazioni e le divergenze successive spiegano perché i geni delle globine (ε, γ, β, δ nel cluster β) si esprimono in fasi diverse: embrione, feto, adulto.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b3a");
T.sp.push("Replicazione nei procarioti. Il cromosoma circolare di E. coli ha una sola origine (oriC), riconosciuta dalla proteina DnaA che apre la doppia elica; l'elicasi DnaB si carica e si formano due forcelle che procedono in direzioni opposte (replicazione bidirezionale, «a theta») fino a incontrarsi. La DNA polimerasi III è l'enzima principale che sintetizza i nuovi filamenti; la DNA polimerasi I rimuove i primer di RNA con l'attività esonucleasica 5'→3' e riempie i buchi; la ligasi chiude i frammenti.");
T.sp.push("Replicazione negli eucarioti. Ogni cromosoma ha migliaia di origini. In G1 il complesso di riconoscimento dell'origine (ORC) lega le origini e, con altri fattori, carica l'elicasi MCM formando il complesso pre-replicativo («licenza»). All'inizio della fase S le chinasi del ciclo attivano l'elicasi e ogni origine si apre in due forcelle; la licenza viene poi bloccata, così ogni tratto è copiato una sola volta per ciclo. Le polimerasi principali sono la α (con la primasi, fa il primer e un breve tratto), la ε (filamento guida) e la δ (filamento ritardato), tenute sul DNA da un anello chiamato PCNA.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b3b");
T.sp.push("Il controllo dell'espressione genica negli eucarioti avviene a più livelli. Trascrizionale: accessibilità della cromatina, fattori di trascrizione, enhancer e silencer decidono se e quanto un gene viene trascritto (è il livello più importante). Post-trascrizionale: splicing alternativo, editing, esportazione dal nucleo e stabilità dell'mRNA (poli-A, miRNA). Traduzionale: regolazione dell'inizio della traduzione, per esempio da proteine che legano le UTR o dalla fosforilazione dei fattori di inizio. Post-traduzionale: modificazioni che accendono o spengono la proteina (fosforilazione), la indirizzano o ne decidono la degradazione (ubiquitinazione).");
T.sp.push("Inizio, allungamento e terminazione della trascrizione eucariotica. Inizio: i fattori generali si assemblano sul promotore (TFIID con TBP sulla TATA box, poi TFIIB, la polimerasi II, TFIIE e TFIIH); TFIIH apre il DNA e fosforila la coda C-terminale della polimerasi, che si stacca dal promotore. Allungamento: la polimerasi procede 5'→3' sul nuovo RNA e la sua coda fosforilata recluta gli enzimi per cappuccio, splicing e poliadenilazione, che lavorano mentre l'RNA viene prodotto. Terminazione: dopo il segnale AAUAAA l'RNA viene tagliato e poliadenilato, e la polimerasi si stacca poco più a valle.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b3c");
T.sp.push("La stabilità dell'mRNA è regolata. Nel citoplasma la coda di poli-A viene accorciata a poco a poco (deadenilazione); quando è troppo corta il cappuccio viene rimosso (decapping) e l'mRNA viene degradato dalle esonucleasi. Sequenze ricche di AU nella 3'UTR accelerano questo processo negli mRNA di breve vita, come quelli di molte citochine. L'RNA interference è un meccanismo di difesa e regolazione: RNA a doppio filamento vengono tagliati da Dicer in siRNA di circa 21 nucleotidi che, nel complesso RISC, guidano il taglio di mRNA perfettamente complementari; i miRNA, prodotti dal genoma stesso come precursori a forcina, si appaiano in modo imperfetto alla 3'UTR e soprattutto riducono la traduzione.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b3d");
T.sp.push("Le regioni non tradotte (UTR) non codificano amminoacidi ma controllano l'mRNA. La 5'UTR, tra il cappuccio e l'AUG, influenza l'efficienza dell'inizio: per esempio nell'mRNA della ferritina contiene una forcina (IRE) che, quando il ferro è poco, lega proteine che bloccano la traduzione. La 3'UTR contiene siti per i miRNA, segnali di stabilità o instabilità e segnali di localizzazione dell'mRNA in parti precise della cellula. Nei procarioti invece il ribosoma trova l'AUG grazie alla sequenza Shine-Dalgarno, a monte del codone di inizio.");
T.sp.push("Gli errori di ripiegamento sono pericolosi: le proteine mal ripiegate espongono parti idrofobiche e tendono ad aggregarsi in fibre ricche di foglietti β (amiloide). Ne sono esempi l'Alzheimer (β-amiloide e tau), il Parkinson (α-sinucleina) e le malattie da prioni, in cui una proteina mal ripiegata induce le copie normali ad assumere la sua forma. La cellula si difende con gli chaperon, che cercano di ripiegare di nuovo, e con il proteasoma, che elimina ciò che non si può recuperare.");
T.sp.push("Esistono proteine simili all'ubiquitina (in inglese ubiquitin-like), come SUMO e NEDD8, che vengono attaccate ad altre proteine con una cascata di enzimi E1-E2-E3 simile a quella dell'ubiquitina. Di solito non mandano la proteina al proteasoma ma ne cambiano la localizzazione (per esempio dentro o fuori dal nucleo), le interazioni o l'attività; la sumoilazione regola molti fattori di trascrizione e proteine della riparazione del DNA. Anche l'ubiquitina non porta sempre alla degradazione: una sola ubiquitina o catene di tipo diverso possono servire per l'endocitosi o per i segnali.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b4b");
T.sp.push("Calcolo delle probabilità in genetica. Regola del prodotto: la probabilità che due eventi indipendenti accadano insieme è il prodotto delle probabilità (figlio maschio E malato = 1/2 × 1/2). Regola della somma: la probabilità che accada l'uno OPPURE l'altro di due eventi che si escludono è la somma (figlio AA oppure Aa = 1/4 + 2/4 = 3/4). Con più geni indipendenti conviene calcolare un gene alla volta e poi moltiplicare, invece di disegnare quadrati di Punnett enormi. Se si sa già che il figlio è sano, si restringe il campo: tra i figli sani di due portatori, 2/3 sono portatori.");
T.sp.push("Epistasi: rapporti mendeliani atipici. Quando due geni agiscono sullo stesso carattere, il rapporto 9:3:3:1 di un diibrido si modifica. Epistasi recessiva 9:3:4 (labrador: l'omozigote ee non deposita pigmento nel pelo, che resta giallo qualunque sia il gene B per nero/marrone). Geni complementari 9:7 (servono entrambi gli alleli dominanti, come due enzimi successivi di una via). Epistasi dominante 12:3:1. Nell'uomo il fenotipo Bombay: chi è omozigote hh non produce l'antigene H, precursore di A e B, e risulta di gruppo 0 anche se ha alleli Iᴬ o Iᴮ.");
T.sp.push("Associazione completa e incompleta. Geni sullo stesso cromosoma tendono a passare insieme: se sono vicinissimi l'associazione è completa e si formano solo gameti parentali; se sono più lontani il crossing over produce anche gameti ricombinanti (associazione incompleta). La frequenza di ricombinanti non supera mai il 50% (il valore dei geni indipendenti). La mappa genetica ordina i geni in base alle frequenze di ricombinazione (1% = 1 centiMorgan); la mappa fisica dà la posizione reale in coppie di basi, oggi nota dal sequenziamento. Nell'uomo 1 cM corrisponde in media a circa 1 milione di bp, ma il rapporto varia perché il crossing over non avviene con la stessa frequenza ovunque.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b4c");
T.sp.push("La trisomia 21 (sindrome di Down, circa 1 nato su 700) ha tre forme. Libera (circa 95%): 47,XX,+21 o 47,XY,+21 per non disgiunzione meiotica, soprattutto nella meiosi I materna, con rischio crescente con l'età materna; non è di solito ereditaria. Da traslocazione robertsoniana (circa 4%): 46 cromosomi di cui uno è la fusione di un 21 con un altro acrocentrico (spesso il 14); un genitore può essere portatore bilanciato con 45 cromosomi, e allora il rischio di ricorrenza è alto. A mosaico (circa 1%): solo una parte delle cellule è trisomica, per errore in una mitosi dopo la fecondazione, con quadro di solito più lieve. Il fenotipo comprende disabilità intellettiva, tratti del volto caratteristici, cardiopatie congenite e maggior rischio di leucemia e Alzheimer precoce.");
}
{const T=BIO_TOPICS.find(t=>t.id==="b4d");
T.sp.push("Come leggere un albero genealogico, in ordine. 1) Il carattere salta generazioni? Se sì, probabilmente recessivo; se compare in ogni generazione, probabilmente dominante. 2) Colpisce soprattutto i maschi? Se sì, pensa alla recessiva legata all'X. 3) C'è trasmissione da padre a figlio maschio? Se sì, escludi l'X. 4) Un padre malato ha tutte le figlie malate e nessun figlio maschio malato? Dominante legata all'X. 5) Passa solo dalle madri, a tutti i figli? Mitocondriale. 6) Solo maschi, sempre da padre a figlio? Legata all'Y. Nella dominante legata all'X le donne malate sono circa il doppio degli uomini, e una madre malata eterozigote trasmette al 50% dei figli di entrambi i sessi.");
}
BIO_TOPICS.find(t=>t.id==="b1d").es.push({q:"Un filamento stampo di DNA è 3'-TACGGA-5'. Qual è la sequenza dell'mRNA trascritto?",p:["l'mRNA è complementare e antiparallelo allo stampo", "T→A, A→U, C→G, G→C"],r:"5'-AUGCCU-3'"});
BIO_TOPICS.find(t=>t.id==="b4b").es.push({q:"Malattia autosomica dominante con penetranza del 70%. Un genitore è eterozigote, l'altro sano. Probabilità che un figlio sia malato?",p:["probabilità di ereditare l'allele: 1/2", "probabilità che l'allele si manifesti: 0,7", "regola del prodotto: 0,5 × 0,7"],r:"0,35, cioè 35%"});
BIO_TOPICS.find(t=>t.id==="b4b").es.push({q:"AaBbCc × AaBbCc (geni indipendenti): probabilità di un figlio aabbcc?",p:["un gene alla volta: aa = 1/4, bb = 1/4, cc = 1/4", "regola del prodotto"],r:"1/64"});
BIO_TOPICS.find(t=>t.id==="b4d").es.push({q:"Una donna con un fratello emofilico e genitori sani sposa un uomo sano. Probabilità che il loro primo figlio maschio sia emofilico?",p:["la madre della donna è portatrice (ha avuto un figlio malato)", "la donna è portatrice con probabilità 1/2", "se è portatrice, un figlio maschio è malato con probabilità 1/2", "1/2 × 1/2"],r:"1/4"});
BIO_TOPICS.find(t=>t.id==="b4c").es.push({q:"Una donna portatrice di traslocazione robertsoniana 14;21 ha 45 cromosomi. Perché è sana ma ha un rischio alto di avere un figlio con sindrome di Down?",p:["ha tutto il materiale genetico, ma il 21 è attaccato al 14", "nella meiosi può dare un gamete con il cromosoma fuso più un 21 libero", "fecondato da un gamete normale → tre copie del 21"],r:"il cariotipo è bilanciato, ma i gameti possono essere sbilanciati: trisomia 21 da traslocazione"});
